protocol StationView: AnyObject {              // class-bound contract
    var query: String { get }
    func showTotal(_ total: Double)
}
final class StationPresenter {
    private weak var view: StationView?
    private let model: StationModel
    init(view: StationView, model: StationModel) {
        self.view = view; self.model = model    // attach
    }
    func queryChanged() { view?.showTotal(model.total(view?.query ?? "")) }
}

final class StationView {                     // passive, closure-based
    var showTotal: ((Double) -> Void)?
    var onQueryChanged: ((String) -> Void)?
}
let view = StationView()
let presenter = StationPresenter(model: model)
view.onQueryChanged = { [weak presenter] q in presenter?.queryChanged(q) }
view.showTotal = { [weak view] total in view?.totalLabel.text = ... }

